  "settings.modelProvider.fieldHelp": "{field} 정보",
  "settings.modelProvider.help.contextWindow":
    "모델이 한 번에 처리할 수 있는 컨텍스트 용량(토큰)입니다. ZCode는 이를 사용해 컨텍스트를 관리합니다.\n모델의 실제 한도를 넘지 마세요.",
  "settings.modelProvider.help.maxOutputTokens":
    "단일 모델 요청에서 생성할 수 있는 최대 토큰 수입니다.\n모델의 실제 한도를 넘지 마세요.",
  "settings.modelProvider.help.inputModalities":
    "모델이 받을 수 있는 콘텐츠 유형을 설정합니다:\n\n- **텍스트**: 텍스트 콘텐츠를 받습니다. 필수입니다.\n- **이미지**: 이미지 콘텐츠를 받습니다.\n- **동영상**: 동영상 콘텐츠를 받습니다.\n- **PDF**: PDF 문서를 직접 받습니다.",
  "settings.modelProvider.help.outputModalities":
    "모델 응답의 콘텐츠 유형입니다. 현재는 텍스트만 지원합니다.",
  "settings.modelProvider.help.capabilities":
    "- **구조화된 출력**: 출력 필드, 유형, 구조에 JSON Schema 제약을 지원합니다.\n- **기본 웹 검색**: 모델 API의 내장 웹 검색 기능을 지원합니다.\n- **대화 중 시스템 메시지**: 대화 중에 시스템 지시를 삽입하는 기능을 지원합니다.\n\n모델이 지원하지 않는 기능은 켜지 마세요.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "채팅에서 사용할 추론 수준을 설정합니다. **추론 강도가 낮은 것부터 높은 순으로 정렬해야 합니다**.\n모델이 지원하지 않는 추론 수준은 구성하지 마세요.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "CEL 표현식으로 현재 추론 수준 `reasoningLevel`을 모델 API 요청 필드에 매핑합니다. 표현식이 반환한 JSON 객체는 전송되는 요청 본문에 병합됩니다.",
  "settings.modelProvider.help.advanced":
    "**MFJS 도구 스키마**: Moonshot Kimi 모델 API에서 주로 사용하는 Moonshot Flavored JSON Schema 호환성을 켭니다. 모델 API가 이 형식을 요구할 때만 켜세요.",
  "settings.modelProvider.help.followRecommendedConfig":
    "모델 ID, 기본 URL, API 형식으로 권장 구성을 찾습니다. ZCode는 권장 사항을 계속 업데이트하고 자동으로 동기화합니다.\n설정을 직접 변경하면 해당 설정은 수동 관리로 바뀌어 권장 업데이트를 따르지 않으며, 나머지 설정은 계속 스마트 구성이 관리합니다.",
